package com.example.demo.jobs;

import com.example.demo.application.commands.AddItemCommand;
import com.example.demo.repository.ItemRepository;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.simple.JdbcClient;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * The two properties a durable queue exists for, against a real database.
 *
 * <p>Neither is observable in a unit test: the first is about what a second
 * process sees, and the second about what survives one dying. The row states
 * are the only evidence either way.
 */
@SpringBootTest
class ItemDispatcherJobIT {

    @Autowired JdbcItemDispatcherStore store;
    @Autowired ItemDispatcherWorker worker;
    @Autowired ItemRepository results;
    @Autowired JdbcClient db;

    @Test
    void acceptedWorkRunsOnceAndReportsItsOutcome() {
        var id = UUID.randomUUID();
        store.enqueue(id, sample());

        assertThat(store.status(id).orElseThrow().state())
                .isEqualTo(ItemDispatcherQueue.State.PENDING);
        worker.runOnce();
        assertThat(store.status(id).orElseThrow().state())
                .isEqualTo(ItemDispatcherQueue.State.SUCCEEDED);

        // Draining again must not run it a second time: a SUCCEEDED row is not
        // runnable, which is what stops a restart replaying the whole queue.
        worker.runOnce();
        assertThat(store.status(id).orElseThrow().attempts()).isEqualTo(1);
    }

    /**
     * The same id twice is the same request; the same id with different work
     * is a mistake, and reporting it is what makes the first case safe.
     */
    @Test
    void reusingAnIdRequiresTheSamePayload() {
        var id = UUID.randomUUID();
        store.enqueue(id, sample());
        store.enqueue(id, sample());
        assertThat(store.status(id).orElseThrow().attempts()).isZero();

        assertThatThrownBy(() -> store.enqueue(id, new AddItemCommand.Input(UUID.fromString("00000000-0000-0000-0000-000000000007"), UUID.fromString("00000000-0000-0000-0000-000000000001"), "sample")))
                .isInstanceOf(ItemDispatcherQueue.IdempotencyConflictException.class);
    }

    private AddItemCommand.Input sample() {
        return new AddItemCommand.Input(UUID.fromString("00000000-0000-0000-0000-000000000001"), UUID.fromString("00000000-0000-0000-0000-000000000001"), "sample");
    }
}
